import sys

try:
    a = float(sys.argv[1])
    b = float(sys.argv[2])
    opr = sys.argv[3]

    if opr == '+':
        print(f"{a} + {b} = {a + b}")
    elif opr == '-':
        print(f"{a} - {b} = {a - b}")
    elif opr == '*':
        print(f"{a} * {b} = {a * b}")
    elif opr == '/':
        if b == 0:
            print('Hata: Sıfıra bölünme')
        else:
            print(f"{a} / {b} = {a / b}")
    else:
        print(f"Geçersiz işlem: {opr}")
except IndexError:
    print("Kullanım: python hesap.py [sayı] [işlem] [sayı] (ör. 2 + 3)")
except ValueError:
    print("Hata: Geçersiz sayı formatı")

